CREATE TYPE "EmployeeStatus" AS ENUM ('ACTIVE','INACTIVE','ON_LEAVE');
CREATE UNIQUE INDEX "User_id_businessId_key" ON "User"("id","businessId");
CREATE TABLE "Employee" ("id" TEXT NOT NULL,"businessId" TEXT NOT NULL,"userId" TEXT,"employeeNumber" TEXT NOT NULL,"firstName" TEXT NOT NULL,"lastName" TEXT NOT NULL,"email" TEXT,"phone" TEXT,"position" TEXT NOT NULL,"salaryMinor" INTEGER,"status" "EmployeeStatus" NOT NULL DEFAULT 'ACTIVE',"hiredAt" TIMESTAMP(3),"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Employee_pkey" PRIMARY KEY ("id"),CONSTRAINT "Employee_salary_check" CHECK ("salaryMinor" IS NULL OR "salaryMinor">=0));
CREATE UNIQUE INDEX "Employee_userId_key" ON "Employee"("userId");CREATE UNIQUE INDEX "Employee_businessId_employeeNumber_key" ON "Employee"("businessId","employeeNumber");CREATE UNIQUE INDEX "Employee_userId_businessId_key" ON "Employee"("userId","businessId");CREATE INDEX "Employee_businessId_status_idx" ON "Employee"("businessId","status");CREATE INDEX "Employee_businessId_position_idx" ON "Employee"("businessId","position");CREATE INDEX "Employee_businessId_lastName_firstName_idx" ON "Employee"("businessId","lastName","firstName");
ALTER TABLE "Employee" ADD CONSTRAINT "Employee_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "Employee" ADD CONSTRAINT "Employee_userId_businessId_fkey" FOREIGN KEY ("userId","businessId") REFERENCES "User"("id","businessId") ON DELETE RESTRICT ON UPDATE CASCADE;
